import os
import argparse
import json
from tqdm import tqdm
from utils.utils import CONSTANTS, CodexTokenizer, load_jsonl, dump_jsonl, make_needed_dir
from utils.build_prompt import build_prompt

class PromptAssembler:
    def __init__(self, input_file, output_file, mode='retrieval', max_tokens=2048):
        self.input_file = input_file
        self.output_file = output_file
        self.mode = mode
        self.max_tokens = max_tokens
        self.tokenizer = CodexTokenizer()

    def run(self):
        # Load the search results generated by search_code.py
        if not os.path.exists(self.input_file):
            print(f"Error: Input file {self.input_file} not found.")
            return

        search_results = load_jsonl(self.input_file)
        final_dataset = []

        print(f"Assembling prompts from {self.input_file}...")
        for case in tqdm(search_results):
            # 1. Extract Repo Name (task_id is usually 'repo/index')
            full_task_id = case['metadata'].get('task_id', 'unknown/0')
            repo_name = full_task_id.split('/')[0]

            # 2. Extract Ground Truth
            ground_truth = case['metadata'].get('ground_truth', '')

            # 3. Build the Prompt using the updated build_prompt.py (C++ comments)
            # max_top_k usually comes from CONSTANTS (10)
            prompt = build_prompt(
                case, 
                self.tokenizer, 
                max_num_tokens=self.max_tokens, 
                max_top_k=CONSTANTS.max_search_top_k, 
                mode=self.mode
            )

            # 4. Create the final object
            output_entry = {
                "task_id": repo_name,
                "prompt": prompt,
                "ground_truth": ground_truth
            }
            final_dataset.append(output_entry)

        # Ensure directory exists and save
        make_needed_dir(self.output_file)
        dump_jsonl(final_dataset, self.output_file)
        print(f"Successfully saved {len(final_dataset)} assembled prompts to {self.output_file}")

if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    # Path to the search result file (e.g., verilog.coarse2fine.10.0.search_res.jsonl)
    parser.add_argument('--input_file_name', type=str, default="vhdl_fim.coarse2fine.10.0")
    # 'retrieval' uses the searched context, 'infile' uses only local file context
    parser.add_argument('--mode', type=str, default='fim_retrieval')
    # Maximum tokens for the LLM prompt (e.g., 1024, 2048, or 4096)
    parser.add_argument('--max_tokens', type=int, default=2048)
    args = parser.parse_args()

    # Construct file paths
    input_path = os.path.join("./search_results", f"{args.input_file_name}.search_res.fim.jsonl")
    output_path = os.path.join("./api_input", f"{args.input_file_name}.prompts.fim.jsonl")

    assembler = PromptAssembler(
        input_file=input_path, 
        output_file=output_path, 
        mode=args.mode,
        max_tokens=args.max_tokens
    )
    assembler.run()